def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    # Determine metaclass from bases
    metaclass = None
    for base in bases:
        if base.__class__ is type:
            continue
        if metaclass is not None and metaclass is not base.__class__:
            raise TypeError("Metaclass conflict: '%s' and '%s'" % (metaclass, base.__class__))
        metaclass = base.__class__
    if metaclass is None:
        metaclass = type
    return metaclass
