def popitem(self):
    """Remove and return the `(key, value)` pair most recently used.

    This method is useful for implementing LRU (least recently used) cache
    algorithms.
    """
    try:
        item = self._OrderedDict.popitem(last=True)
        return (item[0], item[1][0])
    except KeyError, e:
