def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    def linkify_text(match):
        link_type = match.group(1)
        link_text = match.group(2)
        link_url = match.group(3)
        if link_type == "http" or link_type == "https":
            return f"<a href=\"{link_url}\" target=\"_blank\">{link_text}</a>"
        else:
            return f"<a href=\"{link_url}\">{link_text}</a>"

    def linkify_url(match):
        link_text = match.group(0)
        return f"<a href=\"{link_text}\" target=\"_blank\">{link_text}</a>"

    return _LINK_RE.sub(linkify_text, _URL_RE.sub(linkify_url, text))

