def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    # Check if the input is a string
    if not isinstance(tag, str):
        raise TypeError("'tag' must be a string.")
    # Check if the string is empty
    if len(tag) == 0:
        return False
    # Check if the first character is not a letter
    if not tag[0].isalpha():
        return False
    # Check if the remaining characters are not letters, digits, or underscores
    for char in tag[1:]:
        if not (char.isalpha() or char.isdigit() or char == '_'):
            return False
    # If all checks pass, return True
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    children = node.getchildren()
    children_dict = {}
    for child in children:
        child_tag = child.tag
        child_dict = {}
        for k, v in child.attrib.items():
            child_dict[k] = v
        children_dict[child_tag] = child_dict
    return children_dict

