def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if 'include' not in parser_dict:
        return

    include_dict = parser_dict['include']
    for include_key, include_value in include_dict.items():
        if include_key not in self.groups:
            self.groups[include_key] = {}
        include_group = self.groups[include_key]

        for arg_key, arg_value in include_value.items():
            if arg_key not in include_group:
                include_group[arg_key] = arg_value
            else:
                existing_value = include_group[arg_key]
                if isinstance(existing_value, list):
                    existing_value.extend(arg_value)
                elif isinstance(existing_value, Callable):
                    existing_value = self._call_with_existing_args(existing_value, arg_value)
                else:
                    raise ValueError(f"Cannot include value {arg_value} for key {arg_key} in group {include_key}. The existing value is not a list or callable.")
                include_group[arg_key] = existing_value

    del parser_dict['include']

