def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec.

    :param plugin_dir: A path to the plugin's dir.
    :return: A flatten dictionary contains the plugin's properties.
    """
    plugin_spec_file = os.path.join(plugin_dir, 'plugin.spec')
    if not os.path.exists(plugin_spec_file):
        raise FileNotFoundError(f"Plugin spec file not found in '{plugin_dir}'")

    with open(plugin_spec_file) as f:
        plugin_spec = json.load(f)

    flatten_dict = {}

    def _flatten_dict(d, parent_key=''):
        for k, v in d.items():
            key = f'{parent_key}.{k}' if parent_key else k
            if isinstance(v, dict):
                _flatten_dict(v, key)
            else:
                flatten_dict[key] = v

    _flatten_dict(plugin_spec)
    return flatten_dict

